    "explanation": "【2007年原书】正确答案：A（胸廓是否出现适当起伏）。有效通气应使胸廓起伏；胃胀不代表肺部通气有效，还可能增加风险。\n【出处】《危重急症抢救流程解析及规范》（何庆，2007），第四章，原书第12页（PDF第22页）。",
